/// The operations of this module.
pub fn routes() -> OpenApiRouter<AppState> {
    OpenApiRouter::new()
        .routes(routes!(list_contact_relationships, create_contact_relationship))
        .routes(routes!(delete_contact_relationship))
        .routes(routes!(list_contact_pets, create_contact_pet))
        .routes(routes!(update_contact_pet, delete_contact_pet))
        .routes(routes!(list_contact_documents, upload_contact_document))
        .routes(routes!(delete_contact_document))
        .routes(routes!(list_contact_photos, upload_contact_photo))
        .routes(routes!(get_contact_photo, delete_contact_photo))
        .routes(routes!(list_contact_tasks, create_contact_task))
        .routes(routes!(update_contact_task, delete_contact_task))
        .routes(routes!(list_contact_calls, create_contact_call))
        .routes(routes!(update_contact_call, delete_contact_call))
        .routes(routes!(list_contact_groups, add_contact_to_group))
        .routes(routes!(remove_contact_from_group))
        .routes(routes!(list_contact_timeline_events, create_contact_timeline_event))
        .routes(routes!(update_contact_timeline_event, delete_contact_timeline_event))
        .routes(routes!(create_contact_life_event))
        .routes(routes!(update_contact_life_event, delete_contact_life_event))
        .routes(routes!(create_contact_mood_tracking_event))
}
